import { Meta, StoryObj } from "@storybook/react";
import { action } from "storybook/actions";
import { useArgs } from "storybook/preview-api";
import { ShopServicePayment } from "./shop-service-payment";
import { CheckoutService, ICheckoutService } from "@/core/services/checkout-service";
import { GiftCardPaymentResponseItem, UpdatePaymentErrorCode } from "@parksandresorts/webapiproxy-types";
import { PageProviders } from "@/core/providers";
import { ComponentProps } from "react";
import { expect, userEvent, waitFor, within } from "storybook/test";
import { mockCheckoutService, mockProducts } from "./shop-service-payment-shared-storybook";

const meta = {
  title: "Modules/ShopService Payment",
  component: ShopServicePayment,
} satisfies Meta<typeof ShopServicePayment>;

export default meta;

type StoryProps = ComponentProps<typeof ShopServicePayment> & {
  giftCards: Array<GiftCardPaymentResponseItem>;
  withGiftCardInCart: boolean;
};

type Story = StoryObj<StoryProps>;

export const Primary: Story = {
  args: {
    cartId: "test-cart-id",
    enabled: true,
    shopUrlSlugOverrides: undefined,
    giftCards: [],
    withGiftCardInCart: false,
  },
  render: function RenderComponent(_args) {
    const [{ giftCards, withGiftCardInCart, ...args }, setArgs] = useArgs<typeof _args>();
    // Mocking the CheckoutService methods to return the predefined responses
    mockCheckoutService(giftCards, withGiftCardInCart, setArgs);
    return (
      <PageProviders
        currentContentPageData={{ currentLocale: "sv" } as any}
        staticConfigData={{
          eCommerce: {
            preferredPaymentProvider: "Klarna",
            shopServiceCheckoutSlug: "/checkout",
            shopServiceConfirmationSlug: "/confirm",
            shopServicePaymentSlug: "/payment",
          },
          products: mockProducts,
        }}
      >
        <ShopServicePayment {...args} />
      </PageProviders>
    );
  },
};

export const WithGiftCards: Story = {
  ...Primary,
  args: {
    ...Primary.args,
    giftCards: [
      {
        cardIdentifier: "12345678",
        expiresOn: "2024-12-31T23:59:59Z",
        balanceBeforePayment: 1000,
        reservedAmount: 500,
        balanceAfterPayment: 500,
      },
    ],
  },
};

export const ErrorOnAddGiftCard: StoryObj<
  StoryProps & {
    errorType: UpdatePaymentErrorCode;
    errorMessage: string;
  }
> = {
  args: {
    ...Primary.args,
    errorType: UpdatePaymentErrorCode.GIFT_CARD_IS_NOT_VALID,
    errorMessage: "A generic fallback error message",
  },
  argTypes: {
    errorType: {
      control: "select",
      options: Object.values(UpdatePaymentErrorCode),
    },
  },
  render: function RenderComponent(_args) {
    const [{ giftCards, withGiftCardInCart, errorType, errorMessage, ...args }, setArgs] = useArgs<typeof _args>();
    // Mocking the CheckoutService methods to return the predefined responses
    mockCheckoutService(giftCards, withGiftCardInCart, setArgs);
    Object.assign(CheckoutService, {
      addGiftCardToCart: async (cartId, giftCard) => {
        action("addGiftCardToCart")(cartId, giftCard);
        await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
        throw {
          status: 400,
          error: {
            error: errorType,
            message: errorMessage,
            messageSeparator: " - ",
          },
        };
      },
    } satisfies Pick<ICheckoutService, "addGiftCardToCart">);
    return (
      <PageProviders
        currentContentPageData={{ currentLocale: "sv" } as any}
        staticConfigData={{
          eCommerce: {
            preferredPaymentProvider: "Klarna",
            shopServiceCheckoutSlug: "/checkout",
            shopServiceConfirmationSlug: "/confirm",
            shopServicePaymentSlug: "/payment",
          },
          products: { contentfulProducts: [], glkProducts: [] },
        }}
      >
        <ShopServicePayment {...args} />
      </PageProviders>
    );
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await new Promise((resolve) => setTimeout(resolve, 1000)); // Wait for some UI elements to settle

    const addGiftCardButton = canvas.getByTestId("use-gift-card-button");
    await waitFor(() => expect(addGiftCardButton).not.toBeDisabled());
    addGiftCardButton.click();

    await new Promise((resolve) => setTimeout(resolve, 500)); // Wait for modal to open

    canvasElement.querySelector<HTMLLabelElement>('label[for="giftCard-gift-card-or-voucher"]')?.click();
    await new Promise((resolve) => setTimeout(resolve, 200));

    // should automatically focus the card number input
    await userEvent.keyboard("11223344", { delay: 50 });
    const codeInput = canvas.getByLabelText("Shortpass (Obligatoriskt)");
    await userEvent.type(codeInput!, "foo123bar", { delay: 50 });
    await userEvent.keyboard("{Enter}", { delay: 50 });

    waitFor(() => expect(canvas.getByText("Hittar inget presentkort")).toBeInTheDocument());
  },
};

export const CannotPayWithGiftCardWhenInCart: Story = {
  ...Primary,
  args: {
    ...Primary.args,
    withGiftCardInCart: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await new Promise((resolve) => setTimeout(resolve, 1000)); // Wait for some UI elements to settle

    const addGiftCardButton = canvas.getByTestId("use-gift-card-button");
    await waitFor(() => expect(addGiftCardButton).not.toBeDisabled());
    addGiftCardButton.click();

    await new Promise((resolve) => setTimeout(resolve, 500)); // Wait for modal to open

    canvasElement.querySelector<HTMLLabelElement>('label[for="giftCard-gift-card-or-voucher"]')?.click();

    waitFor(() =>
      expect(
        canvas.getByText("Du kan inte använda presentkort som betalmedel när du köper nya presentkort."),
      ).toBeInTheDocument(),
    );
  },
};
