import { minBy } from "lodash-es";
import LanguageHelper from "./language-helper";

const toSekFormatter = (locale: string) =>
  new Intl.NumberFormat(locale, {
    style: "currency",
    currency: "SEK",
    unitDisplay: "short",
    currencyDisplay: "symbol",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  });

const toSekFormatterWithPossiblePrecision = (locale: string) =>
  new Intl.NumberFormat(locale, {
    style: "currency",
    currency: "SEK",
    unitDisplay: "short",
    currencyDisplay: "symbol",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
    trailingZeroDisplay: "stripIfInteger",
  } satisfies Intl.NumberFormatOptions & {
    // This is part of a newer version of ECMAScript, so we need to extend the type here.
    // The fallback is OK, since it always adds 2 frational digits.
    trailingZeroDisplay: "stripIfInteger";
  } as Intl.NumberFormatOptions);

export const formatToSek = (number: number): string => {
  return toSekFormatter(LanguageHelper.getCurrentLocale()).format(number);
};
export const formatToSekWithPossiblePrecision = (number: number): string => {
  return toSekFormatterWithPossiblePrecision(LanguageHelper.getCurrentLocale()).format(number);
};

export const swedishVatRates = [0, 0.06, 0.12, 0.25] as const;
export type SwedishVatRate = (typeof swedishVatRates)[number];

export function getVatRate(priceIncludingVat: number, vatAmount: number): SwedishVatRate {
  if (vatAmount === 0) return 0;

  const approximateVatRate = vatAmount / (priceIncludingVat - vatAmount);
  return minBy(swedishVatRates, (rate) => Math.abs(rate - approximateVatRate))!;
}

export function groupByVatRate<T>(items: T[], getter: (item: T) => { priceIncludingVat: number; vatAmount: number }) {
  return items.reduce(
    (acc, item) => {
      const { priceIncludingVat, vatAmount } = getter(item);
      const vatRate = getVatRate(priceIncludingVat, vatAmount);

      acc[vatRate].items.push(item);
      acc[vatRate].priceIncludingVat += priceIncludingVat;
      acc[vatRate].vatAmount += vatAmount;
      return acc;
    },
    {
      [0]: { items: [], priceIncludingVat: 0, vatAmount: 0 },
      [0.06]: { items: [], priceIncludingVat: 0, vatAmount: 0 },
      [0.12]: { items: [], priceIncludingVat: 0, vatAmount: 0 },
      [0.25]: { items: [], priceIncludingVat: 0, vatAmount: 0 },
    } as Record<SwedishVatRate, { items: Array<T>; priceIncludingVat: number; vatAmount: number }>,
  );
}
